sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;

    // If the connection config was cleared, don't change anything
    if (!newValue) return;

    // Use getReference to fetch the Connection Config record's fields
    g_form.getReference('connection_config', function (configRecord) {
        if (configRecord && configRecord.default_space_key) {
            g_form.setValue('target_space_key', configRecord.default_space_key);
            g_form.addInfoMessage(
                'Target Space Key pre-populated from Connection Config: ' +
                    configRecord.default_space_key
            );
        }
    });
}
